/etc/nginx/sites-available/libretv-produ.source:
server {
 listen 80;
 server_name tv.imqing.cc;
 return 301 https://$host$request_uri;
}
server {
 listen 443 ssl http2;
 server_name tv.imqing.cc;
 ssl_certificate /etc/nginx/ssl/tv.imqing.cc/origin.pem;
 ssl_certificate_key /etc/nginx/ssl/tv.imqing.cc/origin.key;
 ssl_protocols TLSv1.2 TLSv1.3;
 access_log syslog:server=unix:/dev/log,tag=libretv_audit libretv_audit;
 location ^~ /api/ {
  proxy_pass http://127.0.0.1:18080;
  proxy_http_version 1.1;
  proxy_set_header Host $host;
  proxy_set_header X-Forwarded-Proto $scheme;
  proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  proxy_buffering off;
  add_header X-LibreTV-Origin "ovh-libretv-2.21.0" always;
  add_header X-LibreTV-Request-ID $request_id always;
  proxy_read_timeout 300s;
  proxy_hide_header Cache-Control;
  add_header Cache-Control "private, no-store" always;
 }
 location / {
  proxy_pass http://127.0.0.1:18080;
  proxy_http_version 1.1;
  proxy_set_header Host $host;
  proxy_set_header X-Forwarded-Proto $scheme;
  proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
  proxy_buffering off;
  add_header X-LibreTV-Origin "ovh-libretv-2.21.0" always;
  add_header X-LibreTV-Request-ID $request_id always;
  proxy_read_timeout 300s;
 }
}

/etc/nginx/sites-available/libretv-defau.source:
server {
 listen 80 default_server;
 listen [::]:80 default_server;
 server_name _;
 return 444;
}
server {
 listen 443 ssl default_server;
 listen [::]:443 ssl default_server;
 server_name _;
 ssl_reject_handshake on;
 return 444;
}
